<?php require_once 'config/database.php';require_once 'includes/auth.php';require_once 'includes/ui.php';requireProfile($conn);$uid=(int)$_SESSION['user_id'];$st=$conn->prepare("SELECT c.*,f.item_name found_name,fu.name finder_name,l.item_name lost_name FROM claims c JOIN reports f ON f.id=c.report_id JOIN users fu ON fu.id=f.user_id LEFT JOIN reports l ON l.id=c.lost_report_id WHERE c.user_id=? ORDER BY c.created_at DESC");$st->bind_param('i',$uid);$st->execute();$rows=$st->get_result();$titleForTop='Klaim Saya';renderHead('Klaim Saya');renderUserNav('klaim');?><div class="content animate-in"><div class="section-head"><div><h1 class="hero-title">Klaim Saya</h1><p class="muted">Pantau proses klaim dari laporan kehilanganmu.</p></div></div><?php if(isset($_GET['success'])): ?><div class="notice notice-ok">Klaim berhasil dikirim. Sekarang menunggu persetujuan akun penemu.</div><?php endif; ?><div class="grid grid-2 stagger"><?php if($rows->num_rows): while($c=$rows->fetch_assoc()): ?><div class="card"><span class="pill <?= $c['status']==='APPROVED'?'pill-green':($c['status']==='REJECTED'||$c['status']==='FINDER_REJECTED'?'pill-red':'pill-yellow') ?>"><?= e(statusLabel($c['status'])) ?></span><h2><?= e($c['found_name']) ?></h2><div class="meta">Laporan hilang: <?= e($c['lost_name']??'-') ?><br>Penemu: <?= e($c['finder_name']) ?><br>Dibuat: <?= e($c['created_at']) ?></div><div class="timeline"><div class="step done"><div class="dot">✓</div>Kamu</div><div class="step-line"></div><div class="step <?= in_array($c['finder_status'],['APPROVED'])?'done':'current' ?>"><div class="dot">2</div>Penemu</div><div class="step-line"></div><div class="step <?= $c['status']==='APPROVED'?'done':'current' ?>"><div class="dot">3</div>Admin</div></div><?php if($c['finder_note']): ?><div class="notice notice-info">Catatan penemu: <?= e($c['finder_note']) ?></div><?php endif; ?><?php if($c['admin_note']): ?><div class="notice notice-info">Catatan admin: <?= e($c['admin_note']) ?></div><?php endif; ?></div><?php endwhile;else: ?><div class="empty" style="grid-column:1/-1">Belum ada klaim.</div><?php endif; ?></div></div><?php renderFooter(); ?>
